void CEngineMap::OpenDevelopmentStaticMap(CStaticMapBankFile& bank, long mapID)
{
    if (m_staticMapID == mapID)
        return;
    CloseStaticMap();
    unsigned long index = bank.FindEntry(m_mapName);
    if (!index)
        return;
    CByteVector buffer;
    CMemoryDataInputStream stream;
